<script lang="ts">
  /* eslint-disable svelte/no-at-html-tags -- active expeditions from expeditionSnapshot */
  import { expedition } from '../../stores/expedition.svelte.ts';
  import { game } from '../../../gameManager.js';
  import { bindExpeditionLootTooltips } from '../../../expeditionSystem.js';

  let snap = $derived(expedition.snapshot);
  let listEl: HTMLDivElement | undefined = $state();

  $effect(() => {
    const html = snap.activeHtml;
    const el = listEl;
    const gm = game;
    if (!el || !gm) return;
    bindExpeditionLootTooltips(el, gm);
  });
</script>

<div bind:this={listEl} class="quest-container" id="activeExpeditionsContainer">
  <!-- svelte-ignore a11y_no_static_element_interactions -->
  {@html snap.activeHtml}
</div>
